int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    // Mapping from button number to the characters it can produce
    vector<string> keypad = {
        "",      // 0 (unused)
        ".,!?",  // 1
        "abc",   // 2
        "def",   // 3
        "ghi",   // 4
        "jkl",   // 5
        "mno",   // 6
        "pqrs",  // 7
        "tuv",   // 8
        "wxyz"   // 9
    };

    string line;
    while (getline(cin, line)) {
        if (line.empty()) continue;
        string result;
        int n = (int)line.size();
        int i = 0;
        while (i < n) {
            if (line[i] == '0') {
                i++;
                continue;
            }
            int digit = line[i] - '0';
            int count = 0;
            while (i < n && line[i] == digit + '0') {
                count++;
                i++;
            }
            // The character is at index (count-1) % len
            int len = (int)keypad[digit].size();
            if (len > 0) {
                int idx = (count - 1) % len;
                result += keypad[digit][idx];
            }
        }
        cout << result << '\n';
    }

    return 0;
}

