int main(void) {
    int T;
    if (scanf("%d", &T) != 1) return 0;
    getchar(); // consume newline after T

    char line[10000];

    for (int tc = 0; tc < T; tc++) {
        if (!fgets(line, sizeof(line), stdin)) break;

        size_t len = strlen(line);
        if (len && line[len - 1] == '\n') line[--len] = '\0';

        for (size_t i = 0; i < len; ) {
            if (line[i] == ' ') {
                putchar(' ');
                i++;
                continue;
            }

            char d = line[i];
            size_t j = i;
            while (j < len && line[j] == d) j++;
            int cnt = (int)(j - i);

            char ch = '?';
            switch (d) {
                case '2': ch = "abc"[cnt - 1]; break;
                case '3': ch = "def"[cnt - 1]; break;
                case '4': ch = "ghi"[cnt - 1]; break;
                case '5': ch = "jkl"[cnt - 1]; break;
                case '6': ch = "mno"[cnt - 1]; break;
                case '7': ch = "pqrs"[cnt - 1]; break;
                case '8': ch = "tuv"[cnt - 1]; break;
                case '9': ch = "wxyz"[cnt - 1]; break;
                case '0': ch = ' '; break;
            }

            putchar(ch);
            i = j;
        }
        putchar('\n');
    }

    return 0;
}

import java.util.*;
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        // Define keypad mapping
        String[] keypad = new String[10];
        keypad[0] = " ";
        keypad[1] = "1";  // or punctuation
        keypad[2] = "ABC";
        keypad[3] = "DEF";
        keypad[4] = "GHI";
        keypad[5] = "JKL";
        keypad[6] = "MNO";
        keypad[7] = "PQRS";
        keypad[8] = "TUV";
        keypad[9] = "WXYZ";

        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line;
        StringBuilder output = new StringBuilder();

        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                output.append("\n");
                continue;
            }

            StringBuilder result = new StringBuilder();
            int i = 0;
            while (i < line.length()) {
                char c = line.charAt(i);
                if (!Character.isDigit(c)) {
                    i++;
                    continue;
                }
                int digit = c - '0';
                int count = 0;
                while (i < line.length() && line.charAt(i) == c) {
                    count++;
                    i++;
                }
                String chars = keypad[digit];
                int idx = (count - 1) % chars.length();
                result.append(chars.charAt(idx));
            }

            output.append(result.toString()).append("\n");
        }

        System.out.print(output.toString());
    }
}

import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.HashMap;
import java.util.Map;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        Map<Character, String> map = new HashMap<>();
        map.put('1', ".,?\"");
        map.put('2', "abc");
        map.put('3', "def");
        map.put('4', "ghi");
        map.put('5', "jkl");
        map.put('6', "mno");
        map.put('7', "pqrs");
        map.put('8', "tuv");
        map.put('9', "wxyz");
        map.put('0', " ");

        String line = br.readLine();
        if (line == null || line.isEmpty()) return;
        int n = Integer.parseInt(line.trim());

        StringBuilder out = new StringBuilder();

        for (int i = 0; i < n; i++) {
            String s = br.readLine();
            char digit = s.charAt(0);
            String chars = map.get(digit);
            int idx = (s.length() - 1) % chars.length();
            out.append(chars.charAt(idx)).append('\n');
        }

        System.out.print(out.toString());
    }
}
